import{_ as o,o as n,c as r,aw as e}from"./chunks/framework.DLufY-ao.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/common/package-managers/main/compare.md","filePath":"wiki/dev-commit/common/package-managers/main/compare.md"}'),a={name:"wiki/dev-commit/common/package-managers/main/compare.md"};function d(s,t,c,m,g,p){return n(),r("div",null,[...t[0]||(t[0]=[e('<h2 id="сравнение-npm-pnpm-yarn-bun" tabindex="-1">Сравнение Npm, Pnpm, Yarn, Bun <a class="header-anchor" href="#сравнение-npm-pnpm-yarn-bun" aria-label="Permalink to &quot;Сравнение Npm, Pnpm, Yarn, Bun&quot;">​</a></h2><h2 id="таблица-сравнения" tabindex="-1">Таблица сравнения <a class="header-anchor" href="#таблица-сравнения" aria-label="Permalink to &quot;Таблица сравнения&quot;">​</a></h2><blockquote><p>У всех четырёх есть <strong>workspaces</strong> для монорепо; в таблице — то, чем менеджеры <strong>реально расходятся</strong>.</p></blockquote><table tabindex="0"><thead><tr><th>Менеджер</th><th>Главные отличия</th><th>Комментарии</th></tr></thead><tbody><tr><td><strong>npm</strong></td><td>Идёт <strong>вместе с Node</strong>. Версии фиксирует в <code>package-lock.json</code>. Кладёт пакеты в обычный <code>node_modules</code>. Иногда можно импортировать пакет, который <strong>не</strong> записан у вас в <code>package.json</code> (он «подтянулся» с другим пакетом)</td><td>Хватает того, что уже есть с Node; не хочется отдельно ставить другой менеджер</td></tr><tr><td><strong>pnpm</strong></td><td>Ставится <strong>отдельно</strong>. Фиксирует версии в <code>pnpm-lock.yaml</code>. Пакеты хранит <strong>в одном общем месте</strong> на компьютере и подключает в проект ссылками — <strong>меньше занимает места</strong>. Обычно видны только те пакеты, которые вы <strong>сами</strong> указали в <code>package.json</code></td><td>Много проектов на одной машине, монорепо, хочется меньше «случайных» зависимостей</td></tr><tr><td><strong>Yarn</strong></td><td>Ставится <strong>отдельно</strong>. Фиксирует версии в <code>yarn.lock</code>. <strong>Старая ветка (1.x)</strong> — по сути как npm. <strong>Новая (2+)</strong> часто работает <strong>без привычной папки</strong> <code>node_modules</code> (режим PnP) или с ней — как настроите</td><td>Новый Yarn — если хотят PnP или единообразие в команде; старый — часто в старых проектах</td></tr><tr><td><strong>Bun</strong></td><td><strong>Не</strong> входит в Node. Фиксирует версии в <code>bun.lockb</code>. Повторные установки обычно <strong>очень быстрые</strong>. Папка <code>node_modules</code> похожа на npm; по правилам импорта ближе к <strong>npm</strong>, чем к pnpm</td><td>Важна скорость установки и запуска скриптов; иногда ещё запускают код через Bun вместо Node (на своём проекте лучше проверить)</td></tr></tbody></table>',4)])])}const _=o(a,[["render",d]]);export{l as __pageData,_ as default};
